  '✨': g => { ext(g, 'star4', STAR(4, .5, .13), '#e09000', '#ffe050'); ext(g, 'star4', STAR(4, .5, .13), '#e09000', '#ffe050', [.36, .34, .05], .45); ext(g, 'star4', STAR(4, .5, .13), '#e09000', '#ffe050', [-.34, -.3, .05], .35) },
