  '👕': g => { ext(g, 'shirt', SHIRT, '#2a6ab0', '#7ac0f0'); ext(g, 'shirtB', s => { s.moveTo(-.3, -.3); s.lineTo(.3, -.3); s.lineTo(.3, -.38); s.lineTo(-.3, -.38) }, '#f0e8d0', '#ffffff', [0, -.37, .1], 1, [0, 0, 0], .04) },
  '✅': g => { rbox(g, '#3a9a4a', '#8ae07a', [0, 0, 0], [1, 1, .22], [0, 0, 0], .22); ext(g, 'check', CHECK, '#e8f0e0', '#ffffff', [0, 0, .17], .85, [0, 0, 0], .05) },
